package com.yuegang.zhihui.system.api;
import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.system.application.*;import com.yuegang.zhihui.system.security.*;import jakarta.servlet.http.*;import jakarta.validation.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/system") public final class SystemCatalogController{private final SystemCatalogService service;private final SystemTrustedUserContextResolver users;public SystemCatalogController(SystemCatalogService s,SystemTrustedUserContextResolver u){service=s;users=u;}@GetMapping("/dictionaries")ApiResponse<List<DictionaryView>>dictionaries(HttpServletRequest r){users.resolve(r);return ApiResponse.success(service.dictionaries(),TraceIdResolver.resolve(r));}@GetMapping("/feature-flags")ApiResponse<List<FeatureFlagView>>flags(HttpServletRequest r){users.resolve(r);return ApiResponse.success(service.flags(),TraceIdResolver.resolve(r));}@PutMapping("/feature-flags/{key}")ApiResponse<FeatureFlagView>update(@PathVariable String key,@Valid @RequestBody UpdateFeatureFlagRequest body,HttpServletRequest r){var p=users.resolve(r);if(!p.roles().contains("ADMIN"))throw new BusinessException(ErrorCode.PERMISSION_DENIED);return ApiResponse.success(service.updateFlag(key,body,Long.parseLong(p.userId())),TraceIdResolver.resolve(r));}}
